{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "IMDSv1 is not disabled",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "The launch template does not require metadata service session tokens, allowing instances to use IMDSv1. This increases the risk of credential theft through server-side request forgery or other metadata access attacks."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Secrets exposed through launch template user data",
      "resource": "aws_launch_template.web_app",
      "severity": "HIGH",
      "explanation": "The database password is interpolated and an API key is hard-coded into user data, exposing both through Terraform state and EC2 launch template data. Launch template user data is not an appropriate secret delivery mechanism."
    }
  ],
  "patched_code": "resource "aws_launch_template" "web_app" {
  name_prefix   = "automated-employee-onboarding-platform-lt-web-"
  image_id      = data.aws_ami.ubuntu.id
  instance_type = var.instance_type
  key_name      = var.key_pair_name
  vpc_security_group_ids = [aws_security_group.web_app.id]
  user_data = base64encode(<<-EOF
              apt-get update
              apt-get install -y nginx nodejs npm
              systemctl start nginx
              systemctl enable nginx
              EOF
  )

  metadata_options {
    http_tokens = "required"
  }

  tag_specifications {
    resource_type = "instance"
  }
}
",
  "fix_summary": "Required IMDSv2 tokens on launched instances and removed the database password and hard-coded API key from launch template user data. Secrets should instead be retrieved at runtime from an authorized secret store."
}
